(4210595, 607285, 32872, '<td valign="top">Cool effects, lighting and great Halloween colors!!  Love your idea.</td>', 'Cool effects, lighting and great Halloween colors!!  Love your idea.', '2007-11-01 01:14:03.000000', NULL, 1),
(4210598, 607326, 53316, '<td valign="top">Pose is excellent and I like the detail and composition, but I feel that the colors are a little flat/gray overall.</td>', 'Pose is excellent and I like the detail and composition, but I feel that the colors are a little flat/gray overall.', '2007-11-01 01:14:30.000000', NULL, 1),
