(4212334, 607165, 65234, '<td valign="top">Great choice of subject and perspective.</td>', 'Great choice of subject and perspective.', '2007-11-01 13:13:50.000000', NULL, 1),
(4212339, 607456, 65234, '<td valign="top">Poor pumpkin :-(  That looks like a perfectly round specimen.  I know a lot of people who would love to find it ... or would have before today. Soft focus kind of makes it seem more vulnerable.</td>', 'Poor pumpkin :-(  That looks like a perfectly round specimen.  I know a lot of people who would love to find it ... or would have before today. Soft focus kind of makes it seem more vulnerable.', '2007-11-01 13:14:54.000000', NULL, 1),
