(4214098, 607076, 33542, '<td valign="top">This is super creepy  :)  I think I might have liked it better in B&amp;W, but otherwise good.</td>', 'This is super creepy  :)  I think I might have liked it better in B&W, but otherwise good.', '2007-11-01 22:51:02.000000', NULL, 1),
(4214101, 607323, 33542, '<td valign="top">what a cute costume. Was it hot? My only criticism is that the face is a little dark and (perhaps as a result of the camera trying to compensate) there is some color noise throughout the picture.</td>', 'what a cute costume. Was it hot? My only criticism is that the face is a little dark and (perhaps as a result of the camera trying to compensate) there is some color noise throughout the picture.', '2007-11-01 22:51:52.000000', NULL, 1),
