(4230314, 607476, 6519, '<td valign="top">This is one of my favorites in this challenge. I am really impressed with how you managed to take a silly plastic prop, and turn it into a very effective image - thanks to a simple but very appropriate  setting, some careful lighting, a slightly unsettling composition, and some nice post processing.</td>', 'This is one of my favorites in this challenge. I am really impressed with how you managed to take a silly plastic prop, and turn it into a very effective image - thanks to a simple but very appropriate  setting, some careful lighting, a slightly unsettling composition, and some nice post processing.', '2007-11-07 22:12:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4230317, 607456, 6519, '<td valign="top">I love the magical feel to this image.</td>', 'I love the magical feel to this image.', '2007-11-07 22:13:03.000000', NULL, 1),
(4230320, 607185, 6519, '<td valign="top">The lighting could be more appropriate here, I find it a bit too strong. However, I love all the rest  :-)</td>', 'The lighting could be more appropriate here, I find it a bit too strong. However, I love all the rest  :-)', '2007-11-07 22:14:44.000000', NULL, 1),
(4230323, 607274, 6519, '<td valign="top">Oooohhhhhh what a wonderfully spooky scene! Only thing I don''t like is the bright spotlight up in the tree.</td>', 'Oooohhhhhh what a wonderfully spooky scene! Only thing I don''t like is the bright spotlight up in the tree.', '2007-11-07 22:16:21.000000', NULL, 1),
(4230327, 607453, 6519, '<td valign="top">Oh my, how suitable for Halloween and the challenge! I love your post processing, I bet the original doesn''t look anywhere near as good.</td>', 'Oh my, how suitable for Halloween and the challenge! I love your post processing, I bet the original doesn''t look anywhere near as good.', '2007-11-07 22:17:58.000000', NULL, 1),
(4230329, 607257, 6519, '<td valign="top">Oh my..... this is quite the teaser! I am so itching to see the eyes, too! Super shot, love it!</td>', 'Oh my..... this is quite the teaser! I am so itching to see the eyes, too! Super shot, love it!', '2007-11-07 22:19:09.000000', NULL, 1),
(4230337, 607044, 6519, '<td valign="top">Very stunning, professional image.</td>', 'Very stunning, professional image.', '2007-11-07 22:21:42.000000', NULL, 1),
(4230343, 607155, 6519, '<td valign="top">Cute idea, tidy execution, nice colors and composition. Great job with a difficult lighting situation.</td>', 'Cute idea, tidy execution, nice colors and composition. Great job with a difficult lighting situation.', '2007-11-07 22:23:35.000000', NULL, 1),
(4230346, 607441, 6519, '<td valign="top">Cute kids, great pic for this challenge. Your shallow DOF is looking good, but I can''t help wondering if stepping a couple of steps to your right would have given us a better background.</td>', 'Cute kids, great pic for this challenge. Your shallow DOF is looking good, but I can''t help wondering if stepping a couple of steps to your right would have given us a better background.', '2007-11-07 22:24:51.000000', NULL, 1),
(4230359, 607382, 6519, '<td valign="top">This has me intrigued. I don''t normally care for OOF or shaky shots, most of them simply look like a mistake or sloppy work. This one may very well be a happy accident, too (or carefully planned this way), but for some reason I really like it.... it adds an extra element of mystery. The colors are great, also.</td>', 'This has me intrigued. I don''t normally care for OOF or shaky shots, most of them simply look like a mistake or sloppy work. This one may very well be a happy accident, too (or carefully planned this way), but for some reason I really like it.... it adds an extra element of mystery. The colors are great, also.', '2007-11-07 22:28:17.000000', NULL, 1),
(4230372, 607272, 29011, '<td valign="top">Extra points for the humor :D  The age old dog vs cat feud continues!</td>', 'Extra points for the humor :D  The age old dog vs cat feud continues!', '2007-11-07 22:31:45.000000', NULL, 1),
(4230616, 607275, 67697, '<td valign="top">One of my faves for the challenge.  I really love the editing done on this!</td>', 'One of my faves for the challenge.  I really love the editing done on this!', '2007-11-07 23:37:58.000000', NULL, 1),
(4230624, 607479, 67697, '<td valign="top">This is freaky cool and makes me hope that ths were not staged.  Even if it is, I LOVE how the guy in the back is watching you.</td>', 'This is freaky cool and makes me hope that ths were not staged.  Even if it is, I LOVE how the guy in the back is watching you.', '2007-11-07 23:39:06.000000', NULL, 1),
(4230630, 607213, 67697, '<td valign="top">Love it - this is so sweet!  Especially with the two little teeth showing.  Adorable!</td>', 'Love it - this is so sweet!  Especially with the two little teeth showing.  Adorable!', '2007-11-07 23:40:44.000000', NULL, 1),
(4230632, 607305, 67697, '<td valign="top">Very wicked - love it!</td>', 'Very wicked - love it!', '2007-11-07 23:41:20.000000', NULL, 1),
(4230636, 607472, 67697, '<td valign="top">Great find and I love the orange jumping out from the sepia background.  Perfect for a spooky mood.</td>', 'Great find and I love the orange jumping out from the sepia background.  Perfect for a spooky mood.', '2007-11-07 23:42:01.000000', NULL, 1),
(4230637, 607315, 67697, '<td valign="top">Love this and love the fog but wish those two lights were not there on the right.</td>', 'Love this and love the fog but wish those two lights were not there on the right.', '2007-11-07 23:42:30.000000', NULL, 1),
